def world_search(query, top_n=8):
    """Search world API endpoints by keyword; returns short endpoint list. Also check the intent file.
    (query: search text, top_n: max results)"""
    r = tools.mcp__world__api_search(query)
    items = r if isinstance(r, list) else (r.get("results") or r.get("items") or [])
    out = []
    for it in items[:top_n]:
        if isinstance(it, dict):
            out.append({k: it.get(k) for k in ("name", "url", "path", "method", "description", "summary", "title") if k in it and it.get(k)})
        else:
            out.append(str(it)[:200])
    return out

